/// <summary>
/// reviewLines' request. Action: APPROVE, REJECT or RECOUNT. AssignTo (RECOUNT only, optional):
/// the user who should recount - the server enforces that it is not the previous counter.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountReviewRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             userId;
    str             action;
    str             assignTo;
    str             note;
    str             lineNumbersJson;
    List            lineNumbers;

    str     reasonCode;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('Action')]
public str parmAction(str _value = action)
{
    action = _value;
    return action;
}

[DataMemberAttribute('AssignTo')]
public str parmAssignTo(str _value = assignTo)
{
    assignTo = _value;
    return assignTo;
}

[DataMemberAttribute('Note')]
public str parmNote(str _value = note)
{
    note = _value;
    return note;
}

/// <summary>
/// The journal line numbers (reals), read from LineNumbersJson. Not a data member itself: an
/// inbound List binds, but its elements are not X++ reals, so using one fails with a CLR
/// ArgumentNullException ("meth") - the same platform gap as HSMobileOpsPostRequest.parmLinesJson.
/// </summary>
public List parmLineNumbers(List _value = lineNumbers)
{
    System.Object               parsed;
    Newtonsoft.Json.Linq.JArray jArray;
    str                         value;
    int                         lineCount;
    int                         i;

    lineNumbers = _value;
    if (!lineNumbers && lineNumbersJson)
    {
        lineNumbers = new List(Types::Real);
        try
        {
            parsed = Newtonsoft.Json.Linq.JArray::Parse(lineNumbersJson);
        }
        catch (Exception::CLRError)
        {
            return lineNumbers;
        }
        jArray = parsed;
        lineCount = jArray == null ? 0 : jArray.get_Count();
        for (i = 0; i < lineCount; i++)
        {
            value = jArray.get_Item(i).ToString();
            if (value)
            {
                lineNumbers.addEnd(str2num(value));
            }
        }
    }
    return lineNumbers;
}

/// <summary>
/// The journal line numbers as a JSON array of numbers.
/// </summary>
[DataMemberAttribute('LineNumbersJson')]
public str parmLineNumbersJson(str _value = lineNumbersJson)
{
    lineNumbersJson = _value;
    return lineNumbersJson;
}

[DataMemberAttribute('ReasonCode')]
public str parmReasonCode(str _value = reasonCode)
{
    reasonCode = _value;
    return reasonCode;
}
